from collections.abc import Mapping
from html.parser import HTMLParser


class _CatalogParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.entries = []
        self.next_links = []
        self.current = None
        self.depth = 0

    def handle_starttag(self, tag, attrs):
        data = dict(attrs)
        if tag == 'article' and self.current is None and 'data-title' in data:
            self.current = {'title': data['data-title'], 'links': [], 'summaries': []}
            self.depth = 1
            return
        if self.current is not None:
            if tag == 'article':
                self.depth += 1
            if tag == 'a' and data.get('class') == 'detail' and 'href' in data:
                self.current['links'].append(data['href'])
            if tag == 'meta' and data.get('name') == 'summary' and 'content' in data:
                self.current['summaries'].append(data['content'])
        elif tag == 'a' and data.get('rel') == 'next' and 'href' in data:
            self.next_links.append(data['href'])

    def handle_endtag(self, tag):
        if self.current is not None and tag == 'article':
            self.depth -= 1
            if self.depth == 0:
                item = self.current
                self.current = None
                if len(item['links']) == 1 and len(item['summaries']) <= 1:
                    self.entries.append({'title': item['title'], 'link': item['links'][0], 'summary': item['summaries'][0] if item['summaries'] else ''})


def collect_entries(pages, start):
    if not isinstance(pages, Mapping) or not isinstance(start, str):
        raise ValueError('invalid arguments')
    if any(not isinstance(key, str) or not isinstance(value, str) for key, value in pages.items()):
        raise ValueError('pages must map strings to strings')
    result = []
    seen = set()

    def visit(page_id):
        if page_id in seen or page_id not in pages:
            return
        seen.add(page_id)
        parser = _CatalogParser()
        parser.feed(pages[page_id])
        parser.close()
        for target in parser.next_links:
            visit(target)
        result.extend(dict(item) for item in parser.entries)

    visit(start)
    return result

